pinned-horizontal-scroll.jsCode:
const cards = document.querySelector('.horizontal-cards');
if (cards) {
  gsap.to(cards, {
    x: () => -(cards.scrollWidth - window.innerWidth + 120),
    ease: 'none',
    scrollTrigger: {
      trigger: '.horizontal-section',
      pin: true,
      scrub: 1,
      end: () => '+=' + cards.scrollWidth
    }
  });
}
